import React, { useEffect, useRef, useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import Particle from '../Particle';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import remarkMath from 'remark-math';
import rehypeKatex from 'rehype-katex';
import 'katex/dist/katex.min.css';
import mermaid from 'mermaid';
import { FaTwitter, FaLinkedinIn, FaLink, FaTimes } from 'react-icons/fa';
import { getPostBySlug } from '../../posts';
import { useTheme } from '../../ThemeContext';

const blogImageContext = require.context(
  '../../Assets/blogs',
  false,
  /\.(png|jpe?g|gif|webp)$/i,
);
const blogImages = blogImageContext.keys().reduce((images, filePath) => {
  const fileName = filePath.replace('./', '');
  const imageModule = blogImageContext(filePath);
  images[fileName] = imageModule.default || imageModule;
  return images;
}, {});

const blogVideoContext = require.context(
  '../../Assets/blogs',
  false,
  /\.mp4$/i,
);
const blogVideos = blogVideoContext.keys().reduce((videos, filePath) => {
  const fileName = filePath.replace('./', '');
  const videoModule = blogVideoContext(filePath);
  videos[fileName] = videoModule.default || videoModule;
  return videos;
}, {});


// ── Mermaid ────────────────────────────────────────────────────────────────

mermaid.initialize({ startOnLoad: false, theme: 'dark' });

let mermaidCounter = 0;

function MermaidDiagram({ chart }) {
  const [svg, setSvg] = useState('');
  const [error, setError] = useState('');
  const [isExpanded, setIsExpanded] = useState(false);
  const [zoom, setZoom] = useState(1);

  useEffect(() => {
    const id = `mermaid-${++mermaidCounter}`;
    mermaid
      .render(id, chart)
      .then(({ svg }) => setSvg(svg))
      .catch((err) => setError(err.message));
  }, [chart]);

  useEffect(() => {
    if (!isExpanded) return undefined;

    const closeOnEscape = (event) => {
      if (event.key === 'Escape') setIsExpanded(false);
    };
    document.addEventListener('keydown', closeOnEscape);
    return () => document.removeEventListener('keydown', closeOnEscape);
  }, [isExpanded]);

  const openDiagram = () => {
    setZoom(1);
    setIsExpanded(true);
  };

  if (error) return <pre style={{ color: '#f87171' }}>{error}</pre>;
  return (
    <>
      <div
        className='mermaid-diagram'
        role='button'
        tabIndex={0}
        aria-label='Enlarge Mermaid diagram'
        onClick={openDiagram}
        onKeyDown={(event) => {
          if (event.key === 'Enter' || event.key === ' ') openDiagram();
        }}
      >
        <div dangerouslySetInnerHTML={{ __html: svg }} />
      </div>

      {isExpanded && (
        <div
          className='lightbox-overlay blog-image-lightbox'
          role='dialog'
          aria-modal='true'
          aria-label='Enlarged Mermaid diagram'
          onClick={(event) => {
            if (event.target === event.currentTarget) setIsExpanded(false);
          }}
        >
          <button
            type='button'
            className='lightbox-close'
            aria-label='Close enlarged diagram'
            onClick={() => setIsExpanded(false)}
          >
            <FaTimes />
          </button>
          <div
            className='mermaid-lightbox-svg'
            onClick={() => setIsExpanded(false)}
            onWheel={(event) => {
              event.preventDefault();
              setZoom((current) =>
                Math.min(
                  3,
                  Math.max(1, current + (event.deltaY < 0 ? 0.25 : -0.25)),
                ),
              );
            }}
          >
            <div
              className='mermaid-lightbox-zoomed'
              style={{ transform: `scale(${zoom})` }}
              dangerouslySetInnerHTML={{ __html: svg }}
            />
          </div>
        </div>
      )}
    </>
  );
}

function BlogVideo({ src, alt }) {
  const videoFileName = decodeURIComponent(src.split('/').pop());
  const videoSrc = blogVideos[videoFileName] || src;
  return (
    <video
      src={videoSrc}
      autoPlay
      loop
      muted
      playsInline
      className='blog-post-video'
      aria-label={alt || ''}
    />
  );
}

function BlogImage({ src, alt, title }) {
  const [isExpanded, setIsExpanded] = useState(false);
  const [zoom, setZoom] = useState(1);
  const imageFileName = decodeURIComponent(src.split('/').pop());
  const imageSrc = blogImages[imageFileName] || src;

  useEffect(() => {
    if (!isExpanded) return undefined;

    const closeOnEscape = (event) => {
      if (event.key === 'Escape') setIsExpanded(false);
    };
    document.addEventListener('keydown', closeOnEscape);
    return () => document.removeEventListener('keydown', closeOnEscape);
  }, [isExpanded]);

  const openImage = () => {
    setZoom(1);
    setIsExpanded(true);
  };

  if (!isExpanded) {
    return (
      <img
        src={imageSrc}
        alt={alt || ''}
        title={title}
        className='blog-post-image blog-post-image-clickable'
        onClick={openImage}
        onKeyDown={(event) => {
          if (event.key === 'Enter' || event.key === ' ') openImage();
        }}
        role='button'
        tabIndex={0}
      />
    );
  }

  return (
    <>
      <img
        src={imageSrc}
        alt={alt || ''}
        title={title}
        className='blog-post-image blog-post-image-clickable'
        onClick={openImage}
      />
      <div
        className='lightbox-overlay blog-image-lightbox'
        role='dialog'
        aria-modal='true'
        aria-label='Enlarged blog image'
        onClick={(event) => {
          if (event.target === event.currentTarget) setIsExpanded(false);
        }}
      >
        <button
          type='button'
          className='lightbox-close'
          aria-label='Close enlarged image'
          onClick={() => setIsExpanded(false)}
        >
          <FaTimes />
        </button>

        <div
          className='blog-image-lightbox-content'
          onClick={() => setIsExpanded(false)}
          onWheel={(event) => {
            event.preventDefault();
            setZoom((current) =>
              Math.min(
                3,
                Math.max(1, current + (event.deltaY < 0 ? 0.25 : -0.25)),
              ),
            );
          }}
        >
          <img
            src={imageSrc}
            alt={alt || ''}
            className='blog-image-zoomed'
            style={{
              width: `${zoom * 90}vw`,
              maxWidth: '96vw',
              maxHeight: `${zoom * 82}vh`,
              objectFit: 'contain',
            }}
          />
        </div>
      </div>
    </>
  );
}

// ── Utilities ──────────────────────────────────────────────────────────────

function slugify(text) {
  return text
    .toLowerCase()
    .replace(/[^\w\s-]/g, '')
    .trim()
    .replace(/\s+/g, '-');
}

function extractHeadings(content) {
  const matches = [...content.matchAll(/^##\s+(.+)$/gm)];
  return matches.map((m) => {
    const text = m[1].trim();
    return { text, id: slugify(text) };
  });
}

// Custom ReactMarkdown renderers
const markdownComponents = {
  h2: ({ children }) => {
    const text = typeof children === 'string' ? children : String(children);
    return <h2 id={slugify(text)}>{children}</h2>;
  },
  h3: ({ children }) => {
    const text = typeof children === 'string' ? children : String(children);
    return <h3 id={slugify(text)}>{children}</h3>;
  },
  a: ({ children, ...props }) => (
    <a {...props} target='_blank' rel='noopener noreferrer'>
      {children}
    </a>
  ),
  img: (props) =>
    props.src && /\.mp4$/i.test(props.src)
      ? <BlogVideo {...props} />
      : <BlogImage {...props} />,
  code({ inline, className, children }) {
    const language = (className || '').replace('language-', '');
    if (!inline && language === 'mermaid') {
      return <MermaidDiagram chart={String(children).trim()} />;
    }
    return <code className={className}>{children}</code>;
  },
};

// ── Giscus ─────────────────────────────────────────────────────────────────

function GiscusComments() {
  const ref = useRef(null);
  const { theme } = useTheme();
  const giscusTheme = theme === 'dark' ? 'dark_dimmed' : 'light';

  useEffect(() => {
    if (!ref.current) return;
    ref.current.innerHTML = '';

    const script = document.createElement('script');
    script.src = 'https://giscus.app/client.js';
    script.setAttribute('data-repo', 'ankitkr8540/portfolio');
    script.setAttribute('data-repo-id', 'R_kgDOUDFV8w');
    script.setAttribute('data-category', 'Announcements');
    script.setAttribute('data-category-id', 'DIC_kwDOUDFV884DEK_d');
    script.setAttribute('data-mapping', 'url');
    script.setAttribute('data-strict', '0');
    script.setAttribute('data-reactions-enabled', '1');
    script.setAttribute('data-emit-metadata', '0');
    script.setAttribute('data-input-position', 'bottom');
    script.setAttribute('data-theme', giscusTheme);
    script.setAttribute('data-lang', 'en');
    script.crossOrigin = 'anonymous';
    script.async = true;

    ref.current.appendChild(script);
  }, [giscusTheme]); // re-mounts with correct theme on every toggle

  return <div ref={ref} />;
}

// ── Table of Contents ──────────────────────────────────────────────────────

function TableOfContents({ headings, activeId, onLinkClick }) {
  if (headings.length === 0) return null;

  const scrollTo = (id) => {
    const el = document.getElementById(id);
    if (el) el.scrollIntoView({ behavior: 'smooth', block: 'start' });
    onLinkClick(id);
  };

  return (
    <aside className='blog-toc'>
      <p className='blog-toc-label'>On This Page</p>
      <ul className='blog-toc-list'>
        {headings.map((h) => (
          <li
            key={h.id}
            className={`blog-toc-item${activeId === h.id ? ' active' : ''}`}
          >
            <button className='blog-toc-link' onClick={() => scrollTo(h.id)}>
              {h.text}
            </button>
          </li>
        ))}
      </ul>
    </aside>
  );
}

// ── Share Bar ──────────────────────────────────────────────────────────────

function ShareBar({ title, excerpt, tags }) {
  const [copied, setCopied] = useState(false);
  const url = window.location.href;

  const hashtags = (tags || []).map((t) => t.replace(/\s+/g, '')).join(',');

  const tweetText = `${title}\n\n${excerpt}`;

  const twitterUrl =
    `https://twitter.com/intent/tweet` +
    `?text=${encodeURIComponent(tweetText)}` +
    `&url=${encodeURIComponent(url)}` +
    (hashtags ? `&hashtags=${encodeURIComponent(hashtags)}` : '');

  const linkedInUrl =
    `https://www.linkedin.com/shareArticle?mini=true` +
    `&url=${encodeURIComponent(url)}` +
    `&title=${encodeURIComponent(title)}` +
    `&summary=${encodeURIComponent(excerpt || '')}`;

  const copyLink = () => {
    navigator.clipboard.writeText(url).then(() => {
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    });
  };

  return (
    <div className='blog-share-bar'>
      <span className='blog-share-label'>Share</span>
      <a
        href={twitterUrl}
        target='_blank'
        rel='noreferrer'
        className='blog-share-btn'
        aria-label='Share on X'
      >
        <FaTwitter size={14} />
      </a>
      <a
        href={linkedInUrl}
        target='_blank'
        rel='noreferrer'
        className='blog-share-btn'
        aria-label='Share on LinkedIn'
      >
        <FaLinkedinIn size={14} />
      </a>
      <button className='blog-share-copy' onClick={copyLink}>
        <FaLink size={11} />
        {copied ? 'Copied!' : 'Copy link'}
      </button>
    </div>
  );
}

// ── BlogPost ───────────────────────────────────────────────────────────────

function BlogPost() {
  const { slug } = useParams();
  const navigate = useNavigate();
  const post = getPostBySlug(slug);
  const [activeId, setActiveId] = useState('');
  const ignoreScrollUntil = useRef(0);

  const headings = post ? extractHeadings(post.content) : [];

  // Scroll tracker — active = last heading whose top crossed the navbar
  useEffect(() => {
    if (headings.length === 0) return;

    const OFFSET = 100;

    const handleScroll = () => {
      // Don't override an explicit click for 1 second
      if (Date.now() < ignoreScrollUntil.current) return;

      // At bottom of page → last heading is active
      const atBottom =
        window.scrollY + window.innerHeight >=
        document.documentElement.scrollHeight - 60;
      if (atBottom) {
        setActiveId(headings[headings.length - 1].id);
        return;
      }

      let current = headings[0].id;
      for (const { id } of headings) {
        const el = document.getElementById(id);
        if (el && el.getBoundingClientRect().top <= OFFSET) {
          current = id;
        }
      }
      setActiveId(current);
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    handleScroll();

    return () => window.removeEventListener('scroll', handleScroll);
  }, [headings]);

  if (!post) {
    return (
      <div className='blog-page'>
        <div
          className='blog-page-inner'
          style={{ textAlign: 'center', paddingTop: '80px' }}
        >
          <h2 style={{ color: 'white' }}>Post not found.</h2>
          <button
            className='blog-back-btn'
            onClick={() => navigate('/blogs')}
            style={{ marginTop: '16px' }}
          >
            ← Back to Blog
          </button>
        </div>
      </div>
    );
  }

  const { title, date, tags, excerpt } = post.meta;
  const formattedDate = new Date(date).toLocaleDateString('en-US', {
    year: 'numeric',
    month: 'long',
    day: 'numeric',
  });
  const readingTime = Math.ceil(post.content.split(/\s+/).length / 200);

  return (
    <div className='blog-page'>
      <Particle />
      <div className='blog-page-inner'>
        <div className='blog-post-nav'>
          <button className='blog-back-btn' onClick={() => navigate('/blogs')}>
            ← All Posts
          </button>
        </div>

        <div className='blog-post-layout'>
          {/* ── Sidebar TOC (left) ── */}
          <TableOfContents
            headings={headings}
            activeId={activeId}
            onLinkClick={(id) => {
              setActiveId(id);
              ignoreScrollUntil.current = Date.now() + 1000;
            }}
          />

          {/* ── Main article ── */}
          <article className='blog-post-article'>
            <header className='blog-post-article-header'>
              <div
                className='blog-article-tags'
                style={{ marginBottom: '16px' }}
              >
                {tags.map((tag) => (
                  <span key={tag} className='blog-tag'>
                    {tag}
                  </span>
                ))}
              </div>
              <h1 className='blog-post-article-title'>{title}</h1>
              <div className='blog-article-meta' style={{ marginTop: '12px' }}>
                <span className='blog-article-date'>{formattedDate}</span>
                <span className='blog-article-dot'>·</span>
                <span className='blog-article-read'>
                  {readingTime} min read
                </span>
              </div>
            </header>

            <ShareBar title={title} excerpt={excerpt} tags={tags} />

            <div className='blog-post-body'>
              <ReactMarkdown
                remarkPlugins={[remarkGfm, remarkMath]}
                rehypePlugins={[rehypeKatex]}
                components={markdownComponents}
              >
                {post.content}
              </ReactMarkdown>
            </div>
          </article>
        </div>

        <div className='blog-comments-section'>
          <h2>Discussion</h2>
          <p className='blog-comments-hint'>
            Sign in with GitHub to leave a comment.
          </p>
          <GiscusComments />
        </div>
      </div>
    </div>
  );
}

export default BlogPost;
